const { appendFile } = require("node:fs");
const path = require("node:path");

const archivoHistorial = path.join(__dirname, "historial.txt");

function guardarSaludo(texto, callback) {
  appendFile(archivoHistorial, `${texto}\n`, "utf8", callback);
}

module.exports = { guardarSaludo };

const { crearSaludo } = require("./saludos");
const { guardarSaludo } = require("./historial");

const nombre = process.argv.slice(2).join(" ").trim();

if (!nombre) {
  console.error('Uso: node app.js "Tu nombre"');
  process.exitCode = 1;
} else {
  const saludo = crearSaludo(nombre);
  console.log(saludo);

  guardarSaludo(saludo, (error) => {
    if (error) {
      console.error("No se pudo actualizar el historial:", error.message);
      process.exitCode = 1;
      return;
    }

    console.log("Historial actualizado");
  });
}

